.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
.chat-sidebar {
    width: 20%;
    min-width: 200px;
    border-right: 1px solid #e0e0e0;
    background: #f8f9fa;
    overflow-y: auto;
}

.channel-list {
    padding: 0;
}

.channel-list-header {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    color: #333;
    border-bottom: 1px solid #e0e0e0;
}

.channel-item {
    display: block;
    width: 100%;
    padding: 10px 16px;
    border: none;
    background: transparent;
    text-align: left;
    cursor: pointer;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #e9ecef;
}

.channel-item.active {
    background: #d4e5f7;
    border-left: 3px solid #0d6efd;
}

.channel-name-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
    color: #222;
}

.unread-badge {
    background: #dc3545;
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

.channel-description {
    display: block;
    font-size: 0.75rem;
    color: #666;
    margin-top: 2px;
